package com.lin.blog;
import jakarta.persistence.*; import jakarta.validation.constraints.NotBlank; import java.time.LocalDateTime;
@Entity public class Article { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @NotBlank public String title; @Column(unique=true) public String slug; public String category; @Column(length=500) public String excerpt; @Lob @NotBlank public String content; public boolean published=true; public LocalDateTime createdAt=LocalDateTime.now(); public LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();} }
